#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Linq;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Placements;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Grids;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Callbacks;
using MVZ2Logic.Entities;
using MVZ2Logic.Grids;
using MVZ2Logic.Level;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Areas
{
    [AutoAreaDefinition(VanillaAreaNames.mountain)]
    public class Mountain : AreaDefinition
    {
        public Mountain(string nsp, string name) : base(nsp, name)
        {
            SetProperty(VanillaAreaProps.WATER_COLOR, new Color(0, 0.48f, 0.89f, 1));
            SetProperty(VanillaAreaProps.WATER_COLOR_CENSORED, new Color(0, 0.48f, 0.89f, 1));
            AddTrigger(LogicLevelCallbacks.IS_TERRAIN, IsWaterCallback, filter: LogicTerrainTypes.water);
        }
        public override void Setup(LevelEngine level)
        {
            base.Setup(level);
            level.Spawn(VanillaEffectID.miner, new Vector3(600, 0, 40), null);
            level.Spawn(VanillaEffectID.waterfall, new Vector3(100, 0, 120), null);
        }
        public override void Update(LevelEngine level)
        {
            base.Update(level);
            var wave = GetPoolWave(level);
            wave = (wave + 0.01f) % 1;
            SetPoolWave(level, wave);

            var model = level.GetAreaModelInterface();
            if (model != null)
            {
                model.SetModelProperty("WindSpeed", level.GetCurrentDecorativeWindSpeed());
            }
        }
        public override float GetGroundY(LevelEngine level, float x, float z)
        {
            var column = level.GetColumn(x);
            var lane = level.GetLane(z);
            var grid = level.GetGrid(column, lane);
            if (grid != null && grid.IsWater())
            {
                // 水中
                return -1 + Mathf.Sin(((x + z) * 0.01f + GetPoolWave(level)) * 4 * Mathf.PI);
            }
            return base.GetGroundY(level, x, z);
        }
        private void IsWaterCallback(LogicLevelCallbacks.IsTerrainCallbackParams args, CallbackResult result)
        {
            var level = args.level;
            if (level.AreaID != VanillaAreaID.mountain)
                return;
            var column = level.GetColumn(args.x);
            var lane = level.GetLane(args.z);

            if (column >= 0 && column < level.GetMaxColumnCount()) // 不决定场内地块的地形
                return;

            if (lane >= 1 && lane <= 4 && (column <= 9 || column >= 13))
            {
                result.SetValue(true);
            }
        }
        public override void PostHugeWaveEvent(LevelEngine level)
        {
            base.PostHugeWaveEvent(level);
            level.PlaySound(VanillaSoundID.flood);
            for (int i = 0; i < level.GetMaxLaneCount(); i++)
            {
                if (!level.IsWaterLane(i))
                    continue;
                PushWaterLane(level, i);
            }
        }
        public static void PushWaterLane(LevelEngine level, int lane)
        {
            // 找到最左侧有承载层器械的格子
            int startX = -1;
            var columnCount = level.GetMaxColumnCount();
            List<Entity> initialMovers = new List<Entity>();
            for (int col = 0; col < columnCount; col++)
            {
                var grid = level.GetGrid(col, lane);
                if (grid == null || !grid.IsWater())
                    continue;

                initialMovers.Clear();
                var carrierEntities = grid.GetLayerEntities(VanillaGridLayers.carrier);
                if (carrierEntities.Length > 0)
                {
                    initialMovers.AddRange(carrierEntities);
                    startX = col;
                    break;
                }
            }

            if (startX == -1)
            {
                // 河中没有发现承载层器械，无事发生。
                return;
            }

            // 启动点位于第startX行。

            // 收集所有因连锁反应需要移动的器械
            HashSet<Entity> affectedEntities = new HashSet<Entity>();

            // 初始推动：最左侧格子的非悬浮承载层器械（水流直接作用）
            foreach (var mover in initialMovers)
            {
                if (!CalculatePushChain(mover, lane, affectedEntities))
                {
                    return; // 只要有一条链推不动，整个事件失效
                }
            }

            // 如果能推得动，统一向右移动一格
            // 按照坐标从右到左排序更新，避免覆盖逻辑问题（虽然这里是HashSet统一处理，但排序更安全）
            var sortedMovers = affectedEntities.OrderByDescending(a => a.GetColumn()).ToList();
            foreach (var entity in sortedMovers)
            {
                int nextX = entity.GetColumn() + 1;
                if (nextX >= columnCount)
                {
                    var effects = new DamageEffectList(VanillaDamageEffects.OUT_OF_BOUND);
                    entity.Die(effects);
                }
                else
                {
                    entity.StartChangingGrid(nextX, lane, false, speedFactor: 0.1f);
                }
            }
        }

        // 递归计算推动链条，若遇到稳固返回 false，否则返回 true
        private static bool CalculatePushChain(Entity current, int lane, HashSet<Entity> affected)
        {
            // 如果已经加入处理队列，防止死循环（虽然在单向推进中不会，但保持严谨）
            if (affected.Contains(current))
                return true;

            // 1. 如果自身是稳固的，直接宣告推不动
            if (current.IsStableContraption())
                return false;

            affected.Add(current);


            var level = current.Level;
            int currentCol = current.GetColumn();
            int targetCol = currentCol + 1;

            // 规则3：同行连带（如果推了这一格的东西，这一格里压在它头上的、或者被它保护的其它器械也要一起走）
            var sameGridEntities = current.GetCarryingTargets();
            foreach (var ent in sameGridEntities)
            {
                if (ent == current)
                    continue;
                // 不带着悬浮器械移动。
                if (ent.IsSuspendingContraption())
                    continue;
                if (!CalculatePushChain(ent, lane, affected))
                    return false;
            }

            // 如果已经到了边界，后面不会有物理碰撞冲突了（直接出界摧毁）
            if (targetCol >= level.GetMaxColumnCount())
                return true;

            var targetGrid = level.GetGrid(targetCol, lane);
            if (targetGrid == null)
                return true;

            // 规则2 & 3：碰撞冲突（检查目标格子上是否有层级冲突的器械）

            var targetGridEntities = targetGrid.GetEntities();
            var currentGridLayers = current.GetGridLayersToTake();
            if (currentGridLayers != null && currentGridLayers.Length > 0)
            {
                foreach (var targetEntity in targetGridEntities)
                {
                    // 如果目标格子的器械与当前【整个移动集合】在目标位置将要占用的层级有冲突
                    // 简化逻辑：只要当前器械和目标器械有交集层，就会产生碰撞推动
                    var targetLayers = targetEntity.GetGridLayersToTake();
                    if (targetLayers == null || targetLayers.Length <= 0)
                        continue;
                    if (currentGridLayers.Intersect(targetLayers).Count() > 0)
                    {
                        // 递归推动目标格子的器械
                        if (!CalculatePushChain(targetEntity, lane, affected))
                            return false;
                    }
                }
            }
            return true;
        }
        public static float GetPoolWave(LevelEngine level)
        {
            return level.GetProperty<float>(PROP_POOL_WAVE);
        }
        public static void SetPoolWave(LevelEngine level, float value)
        {
            level.SetProperty(PROP_POOL_WAVE, value);
        }
        public static readonly VanillaLevelPropertyMeta<float> PROP_POOL_WAVE = new VanillaLevelPropertyMeta<float>("PoolWave");
    }
}